content.query:
query LuxeStyleProjectorSourceBindings($id: ID!) {
 product(id: $id) {
  id
  sourceFields: metafields(first: 15) { nodes { namespace key type value } pageInfo { hasNextPage endCursor } }
  variants(first: 2) {
   nodes {
    id sku inventoryPolicy
    inventoryItem { tracked }
    sourceFields: metafields(first: 10) { nodes { namespace key type value } pageInfo { hasNextPage endCursor } }
   }
   pageInfo { hasNextPage endCursor }
  }
 }
}
